    func path(in rect: CGRect) -> Path {
        let scale = min(rect.height, rect.width / Self.aspect)
        let dx = rect.midX - Self.aspect * scale / 2, dy = rect.midY - scale / 2
        var path = Path()
        path.addLines(Self.points.map { CGPoint(x: $0.x * scale + dx, y: $0.y * scale + dy) })
        path.closeSubpath()
        return path
    }
